planeResp2 = opsMAT.post.transformResponseStruct(planeResp);
nodeTags = nodeResp2.nodeTags;
time = nodeResp2.time;

idx = nodeTags == 408;
disp_sel = nodeResp2.disp.ux(:, idx);

disp(disp_sel.');  % Data at non-existent time steps will be filled with NAN. %[output:531f8e4a]
figure; %[output:9e93dede]
plot(time(9:end), disp_sel(9:end));  % Remove the first 8 seconds of gravity analysis time %[output:9e93dede]
